218     template<typename T, qualifier Q>
219     GLM_FUNC_QUALIFIER tdualquat<T, Q> dual_quat_identity()
220     {
221         return tdualquat<T, Q>(
222             qua<T, Q>::wxyz(static_cast<T>(1), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0)),
223             qua<T, Q>::wxyz(static_cast<T>(0), static_cast<T>(0), static_cast<T>(0), static_cast<T>(0)));
